{
  "name": "Property Tax Relief for Seniors",
  "eligibility": {
    "age": 65,
    "income_limits": {
      "statewide_programs": [
        {
          "program": "Enhanced STAR (New York State)",
          "limit": "$110,750 or less for the 2026-2027 school year; $113,550 or less for the 2027-2028 school year",
          "how_income_is_counted": "For STAR, income means federal adjusted gross income minus the taxable amount of total IRA distributions.",
          "household_rule": "The income limit applies to the combined incomes of the owners and their spouses who primarily reside on the property beginning with the 2026 benefit year."
        }
      ],
      "new_york_city_programs": [
        {
          "program": "SCHE (Senior Citizen Homeowners' Exemption)",
          "limit": "$58,399 or less for the last calendar year"
        },
        {
          "program": "NYC Enhanced STAR",
          "limit": "$98,700 or less",
          "note": "Available to owners 65 and older; NYC may administer some STAR relief differently than the rest of the state."
        }
      ],
      "senior_citizens_exemption_local_option": {
        "program": "Senior citizens exemption (outside NYC)",
        "limit": "Each county, city, town, village, or school district may set the maximum income limit anywhere from $3,000 to $50,000 for the 50% exemption.",
        "table": [
          {
            "income_limit_option": "$3,000 to $50,000",
            "benefit": "Up to 50% exemption"
          },
          {
            "income_limit_option": "If locality adopts the $50,000 limit and allows increased exemptions",
            "benefit": "50% if income is less than $50,000 but more than $49,000; 55% if less than $49,000 but more than $48,000; 60% if less than $48,000 but more than $47,000; 65% if less than $47,000"
          }
        ]
      }
    },
    "asset_limits": null,
    "other_requirements": [
      "Property must be the applicant's primary residence for SCHE and STAR-based relief.",
      "For Enhanced STAR, one owner must be 65 or older by December 31 of the year of exemption; for jointly owned property, only one spouse or sibling must meet the age rule.",
      "For SCHE in NYC, the property must be owned for at least 12 consecutive months before filing unless the exemption was received on a previously owned residence.",
      "For STAR, the benefit applies only to school district taxes, except in New York City, Buffalo, Rochester, Yonkers, and Syracuse where local administration differs."
    ]
  },
  "benefits": {
    "type": "financial",
    "value": [
      "Enhanced STAR: increased property tax relief on the primary residence; the public-facing amount is not fixed statewide because it depends on the local school tax bill and whether it is delivered as a credit or exemption.",
      "STAR credits for most eligible seniors have been publicly described as checks between $700 and $1,500.",
      "SCHE in NYC: reduces New York City real property tax by 5% to 50%."
    ],
    "varies_by": "region"
  },
  "application": {
    "methods": [
      "Online: https://www.tax.ny.gov (STAR and statewide property tax relief information and registration)",
      "Phone (NY State STAR): (518) 457-2036",
      "Online (NYC SCHE/STAR): NYC Department of Finance property tax benefits pages and NYC 311 SCHE page",
      "In person / mail: NYC Department of Finance for SCHE-related filings"
    ],
    "processing_time": "Not stated as a single statewide timeline in the source material; STAR and SCHE timing can vary by program and locality. NYC SCHE is handled through the Department of Finance, while STAR is administered through New York State and may be received as a credit or exemption.",
    "waitlist": null,
    "forms": [
      "RP-425-MBE (Enhanced STAR exemption application)",
      "SCHE application forms used by the NYC Department of Finance"
    ],
    "documents": [
      "Proof of age",
      "Proof of ownership",
      "Proof that the home is the primary residence",
      "Income documentation for the last calendar year",
      "For STAR/Enhanced STAR: information for all owners and any spouse who primarily resides on the property",
      "For NYC SCHE: documents showing ownership for at least 12 consecutive months if applicable"
    ]
  },
  "geography": {
    "statewide": true,
    "restrictions": "The senior citizens exemption is a local-option exemption outside NYC, so income rules and benefits can vary by county, city, town, village, or school district. STAR is statewide, but it applies only to school district taxes except in certain cities.",
    "regional_variations": "Yes. Outside NYC, the senior citizens exemption depends on whether the local government adopts it and what income cap it sets. In NYC, SCHE is a city program, and STAR can be administered as a credit or exemption depending on the case.",
    "offices_or_providers": [
      "New York State Department of Taxation and Finance",
      "New York City Department of Finance",
      "NYC 311"
    ]
  },
  "official_source": "https://www.tax.ny.gov/pit/property/exemption/seniorexempt.htm",
  "gotchas": [
    "There are multiple senior property tax relief programs in New York, and they are not interchangeable.",
    "Enhanced STAR has an age and income test, but the exact benefit is not a fixed dollar amount statewide.",
    "STAR relief generally applies only to school taxes, not county, town, or city taxes, except in the listed cities.",
    "For 2026 and later, the Enhanced STAR income calculation changed to focus on owners and spouses who primarily reside on the property.",
    "NYC SCHE has its own income limit and ownership rule, which is different from STAR."
  ],
  "data_shape_notes": "This is not one uniform benefit. It is a family of senior property-tax programs with different rules by program, and one of them is local-option rather than truly statewide."
}
